<?php declare(strict_types=1);require_once __DIR__.'/bootstrap.php';admin_require_login();$dir=__DIR__.'/../uploads/products';if(!is_dir($dir))mkdir($dir,0755,true);$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){admin_csrf_check();$action=$_POST['action']??'upload';if($action==='delete'){$name=basename((string)($_POST['filename']??''));$path=$dir.'/'.$name;$relative='uploads/products/'.$name;$s=$pdo->prepare('SELECT COUNT(*) FROM products WHERE image_path=?');$s->execute([$relative]);$used=(int)$s->fetchColumn();if($used>0)$errors[]='This image is assigned to a product. Change the product image before deleting it.';elseif(is_file($path)&&preg_match('/\.(jpg|jpeg|png|webp|gif)$/i',$name)){unlink($path);$_SESSION['flash']='Image deleted.';redirect('media.php');}else $errors[]='File not found.';}else{$f=$_FILES['media_file']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK)$errors[]='Choose an image to upload.';elseif($f['size']>4*1024*1024)$errors[]='Maximum file size is 4 MB.';else{$fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'][$mime]??null;if(!$ext)$errors[]='Only JPG, PNG, WEBP and GIF images are supported.';else{$name=bin2hex(random_bytes(16)).'.'.$ext;if(move_uploaded_file($f['tmp_name'],$dir.'/'.$name)){$_SESSION['flash']='Image uploaded.';redirect('media.php');}$errors[]='Could not save file.';}}}}$files=glob($dir.'/*.{jpg,jpeg,png,webp,gif}',GLOB_BRACE)?:[];admin_page_start('Media library');foreach($errors as $err):?><div class="alert alert-danger"><?=e($err)?></div><?php endforeach;?><div class="panel mb-4"><h2 class="h5">Upload image</h2><form method="post" enctype="multipart/form-data" class="d-flex flex-wrap gap-2 align-items-center"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="upload"><input class="form-control" style="max-width:480px" type="file" name="media_file" accept="image/jpeg,image/png,image/webp,image/gif" required><button class="btn btn-primary">Upload</button></form><small class="text-secondary">Images are stored in uploads/products and can be selected while editing a product.</small></div><div class="row g-3"><?php foreach($files as $file):$name=basename($file);$rel='uploads/products/'.$name;$s=$pdo->prepare('SELECT COUNT(*) FROM products WHERE image_path=?');$s->execute([$rel]);$used=(int)$s->fetchColumn();?><div class="col-6 col-md-4 col-xl-3"><div class="panel h-100"><img src="../<?=e($rel)?>" alt="" class="img-fluid rounded mb-2" style="width:100%;height:160px;object-fit:contain;background:#f8fafc"><div class="small text-break" title="<?=e($name)?>"><?=e(substr($name,0,18))?>…</div><div class="small text-secondary">Used by <?=$used?> product(s)</div><form method="post" class="mt-2" onsubmit="return confirm('Delete this image file?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="filename" value="<?=e($name)?>"><button class="btn btn-sm btn-outline-danger" <?=$used?'disabled':''?>>Delete</button></form></div></div><?php endforeach;?></div><?php if(!$files):?><div class="panel text-secondary">No images uploaded yet.</div><?php endif;?><?php admin_page_end();?>